-- 2. 商机跟进记录 pmis_project_opportunity_follow
-- =====================================================
-- [SKIPPED-CLEANUP] DROP TABLE IF EXISTS pmis_project_opportunity_follow;
CREATE TABLE IF NOT EXISTS pmis_project_opportunity_follow(
    id                BIGSERIAL PRIMARY KEY,
