    deleted           SMALLINT      NOT NULL DEFAULT 0,
    version           INTEGER       NOT NULL DEFAULT 0
);
COMMENT ON TABLE pmis_project_budget_item IS '立项预算明细: 按类别拆解预算,支撑执行期预算占用控制(80% 黄/95% 红)';
