-- =============================================================
-- V1.0.0_026__add_pmis_flow_cc.sql
-- 流程抄送表
--
-- P0-3: 抄送中心（对标钉钉/飞书的"抄送我的"独立 Tab）。
--      CC 节点是工作流的核心协作模型之一。
--      抄送记录独立成表，区别于任务表（无需办理动作），便于：
--        1. 独立查询"抄送我的"
--        2. 抄送接收人可读/未读
--        3. 抄送触发站内信触达
-- =============================================================

-- -------------------------------------------
-- 1. 抄送主表
-- -------------------------------------------
-- [SKIPPED-CLEANUP] DROP TABLE IF EXISTS pmis_flow_cc;
CREATE TABLE IF NOT EXISTS pmis_flow_cc(
