--        pg_size_pretty(pg_relation_size(indexrelid)) AS size,
--        100 * (pg_relation_size(indexrelid) - 100 * current_setting('block_size')::int) / NULLIF(pg_relation_size(indexrelid), 0) AS bloat_pct
--   FROM pg_stat_user_indexes
