-- ============================================================
-- V1.0.0_053__add_rule_tenant_id.sql
-- LiteRule 模块多租户字段预留（与项目其他业务表对齐）
--
-- 说明：
--   项目其他业务表（pmis_project_*、pmis_flow_* 等）已普遍预埋
--   tenant_id BIGINT NOT NULL DEFAULT 1 字段。LiteRule 模块的表
--   此前完全缺失该字段，本次补齐以保持 schema 一致性。
--
--   本迁移仅添加字段与索引，不改变现有查询逻辑（单租户部署下
--   tenant_id 恒为 1）。运行时按租户过滤的能力待 v2.0 多租户化
--   阶段与 TenantContext/TenantLineInnerInterceptor 一并启用。
--   详见 docs/multi-tenant-evaluation.md。
-- ============================================================

-- 1. 规则定义表
ALTER TABLE pmis_rule_def
    ADD COLUMN IF NOT EXISTS tenant_id BIGINT NOT NULL DEFAULT 1;
CREATE INDEX IF NOT EXISTS idx_rule_def_tenant ON pmis_rule_def (tenant_id);
COMMENT ON COLUMN pmis_rule_def.tenant_id IS '租户 ID（单租户部署默认 1，多租户隔离待 v2.0 启用）';

-- 2. 规则版本历史表
ALTER TABLE pmis_rule_version_history
    ADD COLUMN IF NOT EXISTS tenant_id BIGINT NOT NULL DEFAULT 1;
CREATE INDEX IF NOT EXISTS idx_rule_version_tenant ON pmis_rule_version_history (tenant_id);

-- 3. 规则执行轨迹表
ALTER TABLE pmis_rule_execution_trace
    ADD COLUMN IF NOT EXISTS tenant_id BIGINT NOT NULL DEFAULT 1;
CREATE INDEX IF NOT EXISTS idx_rule_trace_tenant ON pmis_rule_execution_trace (tenant_id);

-- 4. 决策表定义表
ALTER TABLE pmis_rule_decision_table
    ADD COLUMN IF NOT EXISTS tenant_id BIGINT NOT NULL DEFAULT 1;
CREATE INDEX IF NOT EXISTS idx_rule_dt_tenant ON pmis_rule_decision_table (tenant_id);

-- 5. 评分卡定义表
ALTER TABLE pmis_rule_scorecard
    ADD COLUMN IF NOT EXISTS tenant_id BIGINT NOT NULL DEFAULT 1;
CREATE INDEX IF NOT EXISTS idx_rule_scorecard_tenant ON pmis_rule_scorecard (tenant_id);

-- 6. 决策树定义表
ALTER TABLE pmis_rule_decision_tree
    ADD COLUMN IF NOT EXISTS tenant_id BIGINT NOT NULL DEFAULT 1;
CREATE INDEX IF NOT EXISTS idx_rule_tree_tenant ON pmis_rule_decision_tree (tenant_id);

-- 7. 脚本规则定义表
ALTER TABLE pmis_rule_script
    ADD COLUMN IF NOT EXISTS tenant_id BIGINT NOT NULL DEFAULT 1;
CREATE INDEX IF NOT EXISTS idx_rule_script_tenant ON pmis_rule_script (tenant_id);

-- 8. 灰度分桶统计表
ALTER TABLE pmis_rule_canary_bucket
    ADD COLUMN IF NOT EXISTS tenant_id BIGINT NOT NULL DEFAULT 1;
CREATE INDEX IF NOT EXISTS idx_rule_canary_bucket_tenant ON pmis_rule_canary_bucket (tenant_id);

-- ====================================================================
-- >>>>>>>>>> END OF V1.0.0_053__add_rule_tenant_id.sql
-- ====================================================================

-- ====================================================================
-- >>>>>>>>>> START OF V1.0.0_054__add_user_org_columns.sql
-- ====================================================================

-- ============================================================
-- V1.0.0_054  P2-2 候选人/变量独立表 — 用户表组织架构字段补全
-- ============================================================
-- 说明：为 pmis_user_account 表补充 dept_id / leader_id / position_code 字段，
--   使工作流引擎的 FlowAssigneeResolver 能够展开：
--     - dept:xxx → 部门下所有成员（按 dept_id 查询）
--     - leader:xxx → 直属上级（按 leader_id 查询）
--     - multi_leader:N → 连续 N 级主管（循环查 leader_id）
--     - position:xxx → 岗位人员（按 position_code 查询）
--
-- 兼容性：所有新增字段允许 NULL，不影响存量数据。
-- ============================================================

-- 1. 用户表加 dept_id（部门 ID）
ALTER TABLE pmis_user_account ADD COLUMN IF NOT EXISTS dept_id BIGINT;
COMMENT ON COLUMN pmis_user_account.dept_id IS '所属部门 ID（关联 pmis_department.id）';

-- 2. 用户表加 leader_id（直属上级用户 ID）
ALTER TABLE pmis_user_account ADD COLUMN IF NOT EXISTS leader_id BIGINT;
COMMENT ON COLUMN pmis_user_account.leader_id IS '直属上级用户 ID（关联 pmis_user_account.id，用于审批人 leader: 展开）';

-- 3. 用户表加 position_code（岗位编码）
ALTER TABLE pmis_user_account ADD COLUMN IF NOT EXISTS position_code VARCHAR(64);
COMMENT ON COLUMN pmis_user_account.position_code IS '岗位编码（如 PM/DEV/QA/SA，用于审批人 position: 展开）';

-- 索引：按部门查询用户（dept: 展开主查询）
CREATE INDEX IF NOT EXISTS idx_pua_dept_id
    ON pmis_user_account(dept_id)
    WHERE deleted = 0 AND dept_id IS NOT NULL;

-- 索引：按岗位查询用户（position: 展开主查询）
CREATE INDEX IF NOT EXISTS idx_pua_position_code
    ON pmis_user_account(position_code)
    WHERE deleted = 0 AND position_code IS NOT NULL;

-- 索引：按上级查询用户（反向查询"谁是某人的下属"，用于多级会签场景）
CREATE INDEX IF NOT EXISTS idx_pua_leader_id
    ON pmis_user_account(leader_id)
    WHERE deleted = 0 AND leader_id IS NOT NULL;

